<script lang="ts">
  import { app } from '$lib/stores.svelte';
  let { onToggle }: { onToggle: () => void } = $props();
  import { Tabs, TabsList, TabsTrigger, TabsContent } from '$lib/components/ui/tabs';
  import { Badge } from '$lib/components/ui/badge';
  import { Button } from '$lib/components/ui/button';
  import { ScrollArea } from '$lib/components/ui/scroll-area';
  import { ChevronDown, ChevronUp } from 'lucide-svelte';
  import AlertsLog from './AlertsLog.svelte';
  import { backend } from '$lib/backend';
  import { formatReading } from '$lib/format';
  let baud = $state(115200), outgoing = $state(''), hex = $state(false);
  function display(bytes: number[]) { return hex ? bytes.map(x => x.toString(16).padStart(2,'0').toUpperCase()).join(' ') : new TextDecoder().decode(new Uint8Array(bytes)).replaceAll('\n', '↵'); }
  async function toggleUart() {
    try { if (app.uartOpen) await backend.uartClose(); else await backend.uartOpen(baud); app.uartOpen = !app.uartOpen; }
    catch (cause) { app.report(cause); }
  }
  async function send() { try { await backend.uartSend(outgoing); outgoing = ''; await app.refreshDetails(); } catch (cause) { app.report(cause); } }
  function center(t: number) { const span = app.viewRange[1]-app.viewRange[0]; app.viewRange = [Math.max(0,t-span/2),Math.max(span,t+span/2)]; app.plotMode = 'recording'; }
  function metric(value: number, kind: 'current' | 'voltage' | 'power') { const v = formatReading(value, kind); return v.number.trim() + ' ' + v.unit; }
  function statMetric(value: number, ch: string) { return ch === 'tp' ? value.toFixed(2) + ' °C' : metric(value, ch === 'mc' || ch === 'ac' ? 'current' : ch === 'mp' || ch === 'ap' ? 'power' : 'voltage'); }
</script>
<section class="drawer" class:closed={!app.drawerOpen} aria-label="Bottom drawer"><Tabs value="alerts" class="drawer-tabs"><div class="drawer-header"><TabsList><TabsTrigger value="alerts">Alerts <Badge variant="secondary">{app.alerts.length}</Badge></TabsTrigger><TabsTrigger value="uart">UART</TabsTrigger><TabsTrigger value="stats">Selection stats</TabsTrigger></TabsList><Button variant="ghost" size="icon" onclick={onToggle} aria-label={app.drawerOpen ? 'Collapse drawer' : 'Expand drawer'}>{#if app.drawerOpen}<ChevronDown size={16}/>{:else}<ChevronUp size={16}/>{/if}</Button></div>{#if app.drawerOpen}<div class="drawer-content"><TabsContent value="alerts"><ScrollArea class="drawer-scroll"><AlertsLog /></ScrollArea></TabsContent><TabsContent value="uart"><div class="uart-controls"><label>Baud <input type="number" min="1" max="3000000" bind:value={baud}/></label><Button size="sm" variant="outline" disabled={!app.connection.connected} onclick={toggleUart}>{app.uartOpen ? 'Close' : 'Open'}</Button><label><input type="checkbox" bind:checked={hex}/> Hex</label></div><div class="uart-log">{#each app.uart as entry}<button onclick={() => center(entry.t)}><time>{entry.t.toFixed(4)} s</time><code>{display(entry.bytes)}</code></button>{/each}</div><form class="uart-send" onsubmit={e => { e.preventDefault(); void send(); }}><input aria-label="UART text to send" placeholder="Send text…" bind:value={outgoing} disabled={!app.uartOpen}/><Button size="sm" disabled={!app.uartOpen || !outgoing}>Send</Button></form></TabsContent><TabsContent value="stats">{#if app.stats}<div class="selection-stats"><div class="stats-table" style:grid-template-columns={'80px repeat('+Object.keys(app.stats.channels).length+', minmax(115px, 1fr))'}><div></div>{#each Object.entries(app.stats.channels) as [ch]}<div class="stats-channel"><i class="swatch" data-channel={ch === 'mc' ? 'current' : ch === 'mv' ? 'voltage' : ch === 'mp' ? 'power' : ch === 'ac' ? 'teal' : ch === 'av' ? 'cyan' : 'aux'}></i>{ch}</div>{/each}{#each ['mean','min','max','rms','p-p'] as row}<strong>{row}</strong>{#each Object.entries(app.stats.channels) as [ch, stat]}<code>{statMetric(row === 'p-p' ? stat.max-stat.min : stat[row as 'mean' | 'min' | 'max' | 'rms'], ch)}</code>{/each}{/each}</div><div class="stats-summary"><div><strong>Duration</strong><code>{((app.range ?? app.viewRange)[1]-(app.range ?? app.viewRange)[0]).toFixed(4)} s</code></div>{#if app.stats.charge_mah != null}<div><strong>Charge</strong><code>{Math.abs(app.stats.charge_mah) < 1 ? (app.stats.charge_mah * 1000).toFixed(3) + ' µAh' : app.stats.charge_mah.toFixed(3) + ' mAh'}</code></div>{/if}{#if app.stats.energy}<div><strong>Energy</strong><code>{Math.abs(app.stats.energy.mwh) < 1 ? (app.stats.energy.mwh * 1000).toFixed(3) + ' µWh' : app.stats.energy.mwh.toFixed(3) + ' mWh'}</code></div><div><strong>Average power</strong><code>{metric(app.stats.energy.average_power, 'power')}</code></div>{/if}</div></div>{:else}<p class="empty-state">Select a range in a recording to view statistics.</p>{/if}</TabsContent></div>{/if}</Tabs></section>
